package com.alphaomegos.annasagenda.support

import com.alphaomegos.annasagenda.model.FlightAirport

/**
 * Reading the flight section's shipped files (06.10), generated by
 * tools/flights/make_flight_assets.py. Pure, so a test reads the very files
 * that ship; a bad line is skipped and reported, the rest is kept.
 */
data class FlightAirportsParse(val airports: Map<String, FlightAirport>, val problems: List<String>)

data class FlightCodesParse(val names: Map<String, String>, val problems: List<String>)

private val IATA_AIRPORT = Regex("[A-Z]{3}")

/** airports.tsv: "IATA ICAO lat lon country tz city name", tab-separated; "#" lines are comments. */
fun parseFlightAirports(text: String): FlightAirportsParse {
    val airports = LinkedHashMap<String, FlightAirport>()
    val problems = mutableListOf<String>()
    text.lineSequence().forEachIndexed { i, raw ->
        val line = raw.trimEnd('\r')
        if (line.isBlank() || line.startsWith("#")) return@forEachIndexed
        val f = line.split('\t')
        val lat = f.getOrNull(2)?.toDoubleOrNull()
        val lon = f.getOrNull(3)?.toDoubleOrNull()
        when {
            f.size != 8 || !f[0].matches(IATA_AIRPORT) || lat == null || lon == null ||
                lat !in -90.0..90.0 || lon !in -180.0..180.0 || f[5].isBlank() ->
                problems += "line ${i + 1}: $line"
            f[0] in airports -> problems += "line ${i + 1}: ${f[0]} again"
            else -> airports[f[0]] = FlightAirport(
                code = f[0], icao = f[1], lat = lat, lon = lon, country = f[4],
                timeZone = f[5], city = f[6].ifBlank { f[7] }, name = f[7],
            )
        }
    }
    return FlightAirportsParse(airports, problems)
}

/** airlines.tsv and aircraft.tsv: "code<TAB>name"; "#" lines are comments. */
fun parseFlightCodes(text: String): FlightCodesParse {
    val names = LinkedHashMap<String, String>()
    val problems = mutableListOf<String>()
    text.lineSequence().forEachIndexed { i, raw ->
        val line = raw.trimEnd('\r')
        if (line.isBlank() || line.startsWith("#")) return@forEachIndexed
        val f = line.split('\t')
        when {
            f.size != 2 || f[0].isBlank() || f[1].isBlank() -> problems += "line ${i + 1}: $line"
            f[0] in names -> problems += "line ${i + 1}: ${f[0]} again"
            else -> names[f[0]] = f[1]
        }
    }
    return FlightCodesParse(names, problems)
}
